import { field, textarea, select, checkbox, htmlEscape, attrEscape, normalizeUrl } from "../tool-core.js";export default {form: `<div class="field-grid">${textarea({id: "sitemapUrls",label: "URL list",value: "https://example.com/|2025-01-15|monthly|0.8\nhttps://example.com/about/|2025-01-10|monthly|0.5\nhttps://example.com/tools/|2025-01-20|weekly|0.9",help: "One URL per line: url|lastmod|changefreq|priority. Lastmod, changefreq, and priority are optional."})}</div>`,generate(root) {const lines = root.querySelector("#sitemapUrls").value.split(/\r?\n/).map(l => l.trim()).filter(Boolean);const validFreqs = ["always","hourly","daily","weekly","monthly","yearly","never"];const urls = lines.map(line => {const [url, lastmod, changefreq, priority] = line.split("|").map(s => s.trim());if (!url) return "";const freq = validFreqs.includes(changefreq) ? changefreq : null;const prio = priority && !isNaN(parseFloat(priority)) ? parseFloat(priority) : null;let entry = ` <url>\n <loc>${attrEscape(normalizeUrl(url))}</loc>`;if (lastmod) entry += `\n <lastmod>${attrEscape(lastmod)}</lastmod>`;if (freq) entry += `\n <changefreq>${freq}</changefreq>`;if (prio !== null) entry += `\n <priority>${prio}</priority>`;entry += `\n </url>`;return entry;}).filter(Boolean);if (urls.length === 0) return { output: "Add URLs to generate a sitemap." };return { output: `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${urls.join("\n")}\n</urlset>` };}};